<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>@page{margin:14px}body{font-family:DejaVu Sans;direction:rtl;font-size:11px}.frame{border:3px solid #111;padding:12px}.title{font-size:18px;font-weight:bold}.code{font-size:16px;text-align:center;border:1px dashed #111;padding:8px;margin:10px 0}</style></head><body><div class="frame"><div class="title">برچسب ارسال AutoCar</div><div>سفارش: {{ $order->number }}</div><div>تاریخ: {{ $jalali->format($shipment->created_at) }}</div><hr><b>گیرنده</b><div>{{ data_get($order->shipping_address,'full_name') }} — {{ data_get($order->shipping_address,'mobile') }}</div><div>{{ data_get($order->shipping_address,'province') }}، {{ data_get($order->shipping_address,'city') }}</div><div>{{ data_get($order->shipping_address,'address') }}</div><div>کدپستی: {{ data_get($order->shipping_address,'postal_code') }}</div><div class="code">{{ $shipment->carrier ?: 'AutoCar' }}<br>{{ $shipment->tracking_code ?: 'بدون کد رهگیری' }}</div><div>وزن: {{ $shipment->weight_grams ? number_format($shipment->weight_grams).' گرم' : '—' }}</div></div></body></html>